#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    int eatenApples(vector<int>& apples, vector<int>& days) {
        using P = pair<int, int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        int n = apples.size();
        int i = 0, ans = 0;
        while (i < n || !pq.empty()) {
            if (i < n && apples[i] > 0) {
                pq.push({i + days[i], apples[i]});
            }
            while (!pq.empty() && pq.top().first <= i) {
                pq.pop();
            }
            if (!pq.empty()) {
                auto [rot, cnt] = pq.top();
                pq.pop();
                ans++;
                if (cnt > 1) {
                    pq.push({rot, cnt - 1});
                }
            }
            i++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int eatenApples(int[] apples, int[] days) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int n = apples.length;
        int i = 0, ans = 0;
        while (i < n || !pq.isEmpty()) {
            if (i < n && apples[i] > 0) {
                pq.offer(new int[]{i + days[i], apples[i]});
            }
            while (!pq.isEmpty() && pq.peek()[0] <= i) {
                pq.poll();
            }
            if (!pq.isEmpty()) {
                int[] top = pq.poll();
                ans++;
                top[1]--;
                if (top[1] > 0) {
                    pq.offer(top);
                }
            }
            i++;
        }
        return ans;
    }
}

/**
 * @param {number[]} apples
 * @param {number[]} days
 * @return {number}
 */
var eatenApples = function(apples, days) {
    const pq = [];
    const push = (item) => {
        pq.push(item);
        let idx = pq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (pq[p][0] > pq[idx][0]) {
                [pq[p], pq[idx]] = [pq[idx], pq[p]];
                idx = p;
            } else break;
        }
    };
    const pop = () => {
        if (pq.length === 0) return null;
        const top = pq[0];
        const last = pq.pop();
        if (pq.length > 0) {
            pq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1;
                let right = 2 * idx + 2;
                let smallest = idx;
                if (left < pq.length && pq[left][0] < pq[smallest][0]) smallest = left;
                if (right < pq.length && pq[right][0] < pq[smallest][0]) smallest = right;
                if (smallest !== idx) {
                    [pq[idx], pq[smallest]] = [pq[smallest], pq[idx]];
                    idx = smallest;
                } else break;
            }
        }
        return top;
    };

    let i = 0;
    let ans = 0;
    const n = apples.length;
    while (i < n || pq.length > 0) {
        if (i < n && apples[i] > 0) {
            push([i + days[i], apples[i]]);
        }
        while (pq.length > 0 && pq[0][0] <= i) {
            pop();
        }
        if (pq.length > 0) {
            ans++;
            pq[0][1]--;
            if (pq[0][1] === 0) {
                pop();
            }
        }
        i++;
    }
    return ans;
};
